/* ---------- Steering ---------- */
/* a run you can steer while it works: its steps, what you told it and what it said back, and a message box. A message
   waits for the step in progress, then applies from the next one; when it changes work already done, the agent asks.
   Its content is 16px from every edge, and the card grows and shrinks with its log (grow()), centred in its stage */
.dm-ste{width:100%;max-width:440px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.dm-ste-h{display:flex;flex-direction:column;padding-bottom:var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-ste-h b{font-weight:500;font-size:14px;line-height:20px}
.dm-ste-st{font-size:12.5px;line-height:18px}
.dm-ste-steps{list-style:none;margin:0;padding:0}
.dm-ste-s{display:flex;align-items:center;gap:var(--dm-s-3);min-height:44px;padding:var(--dm-s-1) 0;font-size:13px}
.dm-ste-g{width:16px;height:16px;display:grid;place-items:center;flex:none;color:var(--dm-faint)}
.dm-ste-g .dm-spin{width:11px;height:11px;color:var(--dm-accent-mark,var(--dm-accent))}
.dm-ste-s.dm-done .dm-ste-g{color:var(--dm-ok)}
.dm-ste-t{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-ste-t b{font-weight:500;line-height:20px}
.dm-ste-t span{font-size:12px;line-height:18px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-ste-t span.dm-shim{font-size:12px}
.dm-ste-s.dm-queued .dm-ste-t b{color:var(--dm-fg2)}
.dm-ste-log{display:flex;flex-direction:column;gap:var(--dm-s-2)}
.dm-ste-log:empty{display:none}
/* what you sent, on the right, with whether it is waiting or applied */
.dm-ste-me{align-self:flex-end;max-width:85%;display:flex;flex-direction:column;align-items:flex-end;gap:var(--dm-s-1)}
.dm-ste-me p{margin:0;padding:var(--dm-s-2) var(--dm-s-3);border-radius:calc(14px * var(--dm-rk)) calc(14px * var(--dm-rk)) var(--dm-r-xs) calc(14px * var(--dm-rk));background:var(--dm-chip);font-size:13px;line-height:1.45}
.dm-ste-q{display:inline-flex;align-items:center;gap:var(--dm-s-1);font-size:12px;color:var(--dm-muted)}
.dm-ste-q .dm-spin{width:9px;height:9px}
.dm-ste-q svg{color:var(--dm-ok)}
/* what the agent said back; a heads-up is a light accent tint (the accent's own tint, taken a little further toward the
   surface), with its icon in the accent, until you answer it. Its answers sit under its words, starting where they start, as
   a chat's replies do: white buttons with a hairline edge on the tint (no shadow: buttons cast none), and the one that acts
   is the primary */
.dm-ste-ag{display:flex;gap:var(--dm-s-3);padding:var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-row);font-size:13px;line-height:1.45}
/* its mark in a 16px column, as the steps' marks are */
.dm-ste-ag>svg{flex:none;box-sizing:content-box;margin-top:3px;padding:0 2px;color:var(--dm-accent-fg,var(--dm-accent))}
.dm-ste-ag.dm-warn{background:color-mix(in srgb,var(--dm-accent-bg) 70%,var(--dm-surface))}
.dm-ste-ag .dm-t{flex:1;min-width:0;display:flex;flex-direction:column;gap:var(--dm-s-2)}
.dm-ste-ag p{margin:0}
.dm-ste-acts{display:flex;flex-wrap:wrap;gap:6px}
.dm-ste-ag .dm-pill.dm-line{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.dm-ste-ag .dm-pill.dm-line:hover{box-shadow:var(--dm-on-tint-btn-h)}}
.dm-ste-ag .dm-muted{font-size:12px}
/* once every step is done: a neutral line with the green tick, no green fill (owner, 18 Nov) */
.dm-ste-sum{display:flex;align-items:center;gap:var(--dm-s-3);min-height:20px;font-size:13px;color:var(--dm-fg2)}
.dm-ste-sum svg{color:var(--dm-ok);flex:none;box-sizing:content-box;padding:0 2px}
.dm-ste-box{display:flex;align-items:center;gap:6px;height:var(--dm-field-h);padding:0 5px 0 var(--dm-s-3);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-ste-box{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.dm-ste-box:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-ste-box input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--dm-fg)}
.dm-ste-box input::placeholder{color:var(--dm-muted)}
.dm-ste-box input:disabled{cursor:not-allowed}
.dm-ste-box input:disabled::placeholder{color:var(--dm-dis)}
.dm-ste-go{width:30px;height:30px;border-radius:50%;background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;flex:none;transition:background .2s}
.dm-ste-go[disabled]{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring)}
/* Clean (owner, 17 and 18 Nov): the content 16px in from each edge, ticks in the vivid green, the replies' buttons Clean's flat
