   and the field's corners less that room; empty, a quiet glyph with no fill, then the ink button fades in under it */
:root[data-style="clean"] .dm-ste-h b,:root [data-style="clean"] .dm-ste-h b,:root [data-style="clean"].dm-ste-h b{letter-spacing:-.01em}
