:root[data-style="clean"] .dm-ste-ag .dm-pill.dm-line,:root [data-style="clean"] .dm-ste-ag .dm-pill.dm-line,:root [data-style="clean"].dm-ste-ag .dm-pill.dm-line{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
