:root[data-style="clean"] .dm-ste-go,:root [data-style="clean"] .dm-ste-go,:root [data-style="clean"].dm-ste-go{position:relative;isolation:isolate;border-radius:calc(var(--dm-r-field) - 5px);background:none;box-shadow:none;transition:transform var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
